frame.store("_bread_rise_answer", { let __signature_4925 = Signature { name: "_bread_rise_answer".into(), positional: vec![], positional_only: 0, defaults: vec![], keyword_only: vec![], varargs: None, varkw: None }; let __attrs_4927 = Value::dict(); __attrs_4927.dict_set(Value::from("__doc__"), Value::from("Why a loaf or a dough is slow, worded for the prove the person is actually doing.\n\n    A night in the fridge is a deliberate slow prove - telling that person to find somewhere warm\n    undoes it - and \"do I need to prove it twice\" is a question about the second, shaped prove.\n    The time comes first, because that is what was asked; the reason follows it.\n    "))?; __attrs_4927.dict_set(Value::from("__defaults__"), Value::None)?; let __kwdefaults_4928 = Value::dict(); __attrs_4927.dict_set(Value::from("__kwdefaults__"), Value::None)?; let __closure_4924 = Frame::module(frame.globals.clone()); let mut __function_4926 = NativeFunction::qualified_with_origin("_bread_rise_answer".into(), "_bread_rise_answer".into(), "bot.knowledge.cooking".into(), __attrs_4927, pyrt::object::FunctionOrigin { span: pyrt::runtime::SourceSpan { file: "bot/knowledge/cooking.py", first: 8091, last: 8133, qualname: "_bread_rise_answer" }, closure: __closure_4924.clone(), freevars: vec![] }, move |rt, args| __py_240::_bread_rise_answer(rt, __closure_4924.clone(), &__signature_4925, args)); __function_4926 })?;
let __v_4929 = Value::from("Bitter coffee is over-extracted: grind it coarser, let the water come off the boil for half a minute, and take it off the grounds sooner - about 4 minutes in a cafetiere, 25 to 30 seconds for an espresso. Sour is the same dial the other way and wants a finer grind, hotter water and a little longer. Stale beans and a dirty machine make both, and instant tastes bitter when it is made with boiling water - let the kettle rest first.");
frame.store("_COFFEE_BITTER", __v_4929.clone())?;
let __v_4930 = Value::from("Sour coffee is under-extracted: grind it finer, use water just off the boil rather than boiling, and give it longer on the grounds - about 4 minutes in a cafetiere, 25 to 30 seconds for an espresso. Bitter is the same dial the other way and wants a coarser grind and a shorter brew. A sour note that only shows up with milk is usually the milk.");
